// Go, rút gọn
func hedged(ctx context.Context, delay time.Duration, call func(context.Context) (R, error)) (R, error) {
  ctx, cancel := context.WithCancel(ctx)
  defer cancel()
  ch := make(chan result, 2)
  go func() { r, e := call(ctx); ch <- result{r, e} }()
  select {
  case res := <-ch:
    return res.r, res.e
  case <-time.After(delay):
    go func() { r, e := call(ctx); ch <- result{r, e} }()
  }
  res := <-ch
  return res.r, res.e
}
